async function loadLeaderBackendData(){
  if(state.authStatus!=='authenticated'||!hasLiveLeaderAccess()){
    state.backendData.leader={status:state.authStatus==='authenticated'?'permission-denied':'idle',items:[],error:''};
    state.backendData.roster={status:'permission-denied',eventId:null,items:[],error:'当前账号不是目标社团的 active leader/admin。'};
    return;
  }
  state.backendData.leader={status:'loading',items:[],error:''};
  state.backendData.roster={status:'idle',eventId:null,items:[],error:''};
  try{
    const rows=await backend.getLeaderEvents();
    const items=(rows||[]).map(backendLeaderEventToView);
    state.backendData.leader={status:items.length?'ready':'empty',items,error:''};
    ensureLeaderContext();
  }catch(error){state.backendData.leader={status:'error',items:[],error:error.message||'社长活动读取失败'};state.backendData.roster={status:'error',eventId:null,items:[],error:error.message||'社长活动读取失败'};}
}
async function loadLeaderTransferCandidates(){
  if(!hasLiveLeaderAccess()){
    state.clubTransfer={status:'permission-denied',clubId:state.leaderClubId,items:[],error:'当前账号不是目标社团的 active leader/admin。'};
    leaderConsole('transfer');return;
  }
  const club=leaderClubs().find(item=>item.id===state.leaderClubId)||leaderClubs()[0];
  if(!club){state.clubTransfer={status:'permission-denied',clubId:null,items:[],error:'没有可管理的真实社团。'};leaderConsole('transfer');return;}
  state.leaderClubId=club.id;
  state.clubTransfer={status:'loading',clubId:club.id,items:[],error:''};
  leaderConsole('transfer');
  try{
    const items=await backend.getLeaderTransferCandidates(club.id);
    if(state.leaderClubId!==club.id)return;
    state.clubTransfer={status:items.length?'ready':'empty',clubId:club.id,items,error:''};
  }catch(error){
    if(state.leaderClubId!==club.id)return;
    const denied=error.code==='42501'||/无权|权限|permission denied/i.test(error.message||'');
    state.clubTransfer={status:denied?'permission-denied':'error',clubId:club.id,items:[],error:error.message||'候选人读取失败'};
  }
  leaderConsole('transfer');
}
async function loadLeaderEventRoster(eventId){
  if(state.backendData.leader.status!=='ready'||!hasLiveLeaderAccess()||!eventId)return;
  state.backendData.roster={status:'loading',eventId,items:[],error:''};
  if(state.leaderPreview)leaderConsole('roster');
  try{const rows=await backend.getLeaderEventRoster(eventId);state.backendData.roster={status:rows.length?'ready':'empty',eventId,items:rows.map(backendLeaderRosterToView),error:''};}
  catch(error){state.backendData.roster={status:'error',eventId,items:[],error:error.message||'报名名单读取失败'};}
  if(state.leaderPreview)leaderConsole('roster');
}
async function loadBackendData(){
  await backend.ready;
  if(backend.status==='unconfigured'||backend.status==='unavailable'){state.backendData.events.status='demo';state.backendData.clubs.status='demo';state.backendData.leader={status:'demo',items:[],error:''};state.backendData.roster={status:'demo',eventId:null,items:[],error:''};render();return;}
  if(!backend.client){const message=backend.error||'后端初始化失败';state.backendData.events={status:'error',items:[],error:message};state.backendData.clubs={status:'error',items:[],error:message};state.backendData.leader={status:'error',items:[],error:message};state.backendData.roster={status:'error',eventId:null,items:[],error:message};return;}
  state.backendData.events.status='loading';state.backendData.clubs.status='loading';render();
  const results=await Promise.allSettled([backend.getPublishedEvents(),backend.getPublicClubs()]);
  const [eventResult,clubResult]=results;
  if(eventResult.status==='fulfilled'){const items=(eventResult.value||[]).map(backendEventToView);state.backendData.events={status:items.length?'ready':'empty',items,error:''};syncLiveEventRegistrations();}else state.backendData.events={status:'error',items:[],error:eventResult.reason?.message||'活动请求失败'};
  if(clubResult.status==='fulfilled'){const items=(clubResult.value||[]).map(backendClubToView);state.backendData.clubs={status:items.length?'ready':'empty',items,error:''};}else state.backendData.clubs={status:'error',items:[],error:clubResult.reason?.message||'社团请求失败'};
  await loadLeaderBackendData();
  if(state.page)render();
}
