function applyTheme(themeId=defaultTheme){let resolved=resolveTheme(themeId),theme=resolved.theme;state.theme=theme.id;document.documentElement.dataset.theme=theme.id;document.documentElement.dataset.themeVersion=theme.version;document.documentElement.dataset.themeSchema=String(theme.schemaVersion);document.documentElement.style.colorScheme=theme.colorScheme||'dark';document.documentElement.dataset.themeMotion=theme.motion?.transition||'p5-slice';document.documentElement.dataset.themeSound=theme.motion?.soundProfile||'phantom-command';let missing=missingThemeTokens(theme.id);if(missing.length&&theme.id!==defaultTheme){resolved=resolveTheme(defaultTheme);theme=resolved.theme;state.theme=theme.id;document.documentElement.dataset.theme=theme.id;document.documentElement.dataset.themeVersion=theme.version;document.documentElement.dataset.themeSchema=String(theme.schemaVersion);document.documentElement.style.colorScheme=theme.colorScheme||'dark';document.documentElement.dataset.themeMotion=theme.motion?.transition||'p5-slice';document.documentElement.dataset.themeSound=theme.motion?.soundProfile||'phantom-command';missing=missingThemeTokens(theme.id)}const meta=$('#theme-color');if(meta)meta.content=theme.themeColor;const logo=$('#theme-logo');if(logo){logo.src=theme.assets?.logo||'';logo.alt=theme.id==='blue-archive'?'Blue Archive 官方 Logo':'';logo.toggleAttribute('aria-hidden',!theme.assets?.logo)}const advisorAvatar=$('#advisor-avatar');if(advisorAvatar){advisorAvatar.src=themeAdvisorImage();advisorAvatar.alt=theme.id==='p5'?'主题顾问角色':theme.id==='blue-archive'?'学生顾问角色':'网络节点顾问图形';}const orgProfiles={p5:['幻','幻影动漫社','星海大学 · 示例社团'], 'blue-archive':['S','学生自治委员会','基地 · 本地演示'], 'neon-grid':['N','节点联络社','LOCAL NETWORK · DEMO']};const org=orgProfiles[theme.id]||orgProfiles.p5;const orgMark=$('#org-mark'),orgName=$('#org-name'),orgSubtitle=$('#org-subtitle');if(orgMark)orgMark.textContent=org[0];if(orgName)orgName.textContent=org[1];if(orgSubtitle)orgSubtitle.textContent=org[2];const splash=$('#dialog-splash');if(splash)splash.innerHTML=theme.id==='p5'?'PHANTOM<br>NETWORK':theme.id==='blue-archive'?'SCHale<br>NETWORK':'NODE<br>CONSOLE';if(transitionVideo){transitionVideo.src=`${theme.assets?.transition||themeRegistry[defaultTheme]?.assets?.transition||''}${theme.assets?.transitionFile||'media3.mp4'}`;}if(resolved.errors.length)console.warn('[theme] 已回退默认主题',resolved.errors);if(missing.length)console.error('[theme] 缺少必需 CSS 令牌',missing);return {theme,missingCssTokens:missing,usedFallback:resolved.fallback}}
window.CLUB_THEME_RUNTIME=Object.freeze({contract:themeContract,validate:validateThemeDefinition,inspect:inspectTheme,apply:applyTheme});
function showPageIntro(page=state.page){const info=activeTheme().pageIntros?.[page];if(!info||!pageIntro)return;clearTimeout(showPageIntro.timer);pageIntro.classList.remove('show');pageIntro.dataset.component='page-intro';pageIntro.dataset.motion=activeTheme().motion?.intro||'p5-cut';pageIntro.dataset.state='ENTERING';pageIntro.innerHTML=`<div class="page-intro-speedlines" aria-hidden="true"></div><div class="page-intro-card"><span class="page-intro-index">${esc(info.index)}</span><div><small>${esc(info.code)}</small><strong>${esc(info.title)}</strong><em>${esc(info.cue)}</em></div></div>`;pageIntro.setAttribute('aria-hidden','false');requestAnimationFrame(()=>pageIntro.classList.add('show'));const introDuration=activeTheme().id==='p5'?(state.reduced?650:780):(state.reduced?850:1050);showPageIntro.timer=setTimeout(()=>{pageIntro.classList.remove('show');pageIntro.dataset.state='IDLE';pageIntro.setAttribute('aria-hidden','true')},introDuration)}
const p5Empty=(titleText,body,label='NO SIGNAL')=>`<div class="p5-empty-state"><img src="${themeAsset('feedback','empty-morgana.webp')}" alt="沮丧的摩尔加纳风格提示角色"><div><small>${esc(label)}</small><h2>${esc(titleText)}</h2><p>${esc(body)}</p></div></div>`;
const inlineStatus=(kind,titleText,body='',id='',variant='')=>{const profile=statusProfiles[kind]||statusProfiles.info;return `<div class="p5-inline-status ${kind}${variant?` ${esc(variant)}`:''}" data-component="status-receipt" data-variant="${kind}" data-state="${profile.code}"${id?` id="${esc(id)}"`:''}><span aria-hidden="true">${profile.mark}</span><div><small>${profile.code}</small><b>${esc(titleText)}</b>${body?`<p>${esc(body)}</p>`:''}</div></div>`};
function title(kicker,text,em=''){return `<div class="slash-title compact-title"><small>${kicker}</small><h1>${text}${em?` <em>${em}</em>`:''}</h1></div>`;}
const formationInfo=e=>{const target=Number(e.minParticipants)||0,threshold=e.formationMode==='threshold'&&target>0,ready=!threshold||e.count>=target;return {threshold,target,ready,label:threshold?(ready?'已成团':'等待成团'):'无需等人成团',ratio:threshold?Math.min(100,Math.round(e.count/target*100)):100}};
const eventSignal=e=>{if(!e)return {label:'暂无活动',meta:'去活动页看看新的任务',action:'goto',id:'events'};const f=formationInfo(e);return {label:e.title,meta:`${e.date.split(' · ')[0]} · ${f.label} · ${e.count}/${e.capacity}`,action:'event',id:e.id};};
const formationBlock=(e,compact=false)=>{const f=formationInfo(e);return `<div class="formation-block ${f.ready?'ready':'waiting'} ${compact?'compact':''}" data-formation-state="${f.ready?'ready':'waiting'}"><div><b>${f.label}</b><span>${f.threshold?`${e.count} / ${f.target} 人达到最低人数`:`报名后立即保留席位 · 当前 ${e.count}/${e.capacity}`}</span></div>${f.threshold?`<div class="formation-track" role="progressbar" aria-label="成团进度" aria-valuemin="0" aria-valuemax="${f.target}" aria-valuenow="${Math.min(e.count,f.target)}"><i style="width:${f.ratio}%"></i></div>`:''}</div>`};
function eventCard(e){const mine=state.registrations.get(e.id),liked=state.interest.has(e.id),needsCompanion=state.companions.has(e.id),formation=formationInfo(e);return `<article class="mission-card" data-component="mission-card" data-club-id="${esc(e.clubId||'')}" data-variant="${e.type==='正式活动'?'official':'member'}" data-state="${mine||formation.label}"><span class="kind">${e.type}</span><span class="event-club-label">${esc(eventClubLabel(e.clubId))}</span><h2>${esc(e.title)}</h2><p>◷ ${e.date}</p><p>⌖ ${esc(e.place)}</p><div class="event-signal-row"><span class="status">${mine?`你的状态 / ${mine}`:`${e.status} · ${e.count}/${e.capacity}`}</span></div>${formationBlock(e,true)}<div class="event-card-actions"><button class="p5-button ghost" data-action="interest" data-id="${e.id}" aria-pressed="${liked}">${liked?'已记兴趣':'有点兴趣'}</button><button class="p5-button ghost" data-action="companion" data-id="${e.id}" aria-pressed="${needsCompanion}">${needsCompanion?'已找同行':'想找同行'}</button><button class="event-open" data-action="event" data-id="${e.id}" aria-label="查看${esc(e.title)}活动预览">查看预览 ↗</button></div><img src="${themeEventImage(e)}" alt=""></article>`;}
function hub(){const c=pageCopy('hub'),list=activeEvents(),interestCount=state.interest.size,companionCount=state.companions.size,next=list.find(e=>e.type==='正式活动'&&e.count<e.capacity)||list[0],signal=eventSignal(next);return `<section class="screen hub-screen" data-page="hub" data-theme-surface="hero"><video class="screen-bg hero-video" src="${activeTheme().assets?.hero||`${video}hero-web.mp4`}" autoplay muted loop playsinline></video><div class="screen-shade"></div><div class="hero-copy" data-component="hub-hero">${title(c.eyebrow||'AFTER SCHOOL, TOGETHER',c.title||'放学后，',c.titleEm||'一起去！')}<p class="lead">${c.lead||'先看看今天有哪些轻松的活动。不需要马上报名，也可以先表达一点兴趣。'}</p><div class="hero-actions">${p5btn(c.task||'看看今天的活动 ↗','goto','events','white')}${p5btn(c.gather||'发起一个小聚','gathering','','red')}</div></div><aside class="hero-sticker" data-component="hub-sticker"><span>${c.stickerTop||'LOW PRESSURE CLUB'}</span><b>${c.stickerMain||'GO<br>AT<br>YOUR<br>PACE.'}</b><span>${c.stickerBottom||'先找到同行的人，再一起出发。'}</span></aside><div class="quick-deck" data-component="hub-quick-deck"><button class="quick-card" data-component="mission-card" data-state="READY" data-action="${signal.action}" data-id="${signal.id}"><small>${c.deckLabel||'TODAY / LIVE SIGNALS'}</small><b>${c.mission||'NEXT ACTIVITY'} · ${esc(signal.label)}</b><span>${esc(signal.meta)}</span><i>01</i></button><button class="quick-card" data-component="mission-card" data-state="READY" data-action="goto" data-id="events"><small>LOW-PRESSURE SIGNAL</small><b>${interestCount} 个兴趣记录 / ${companionCount} 个同行需求</b><span>不占名额，仅用于本地演示</span><i>♡</i></button><button class="quick-card" data-component="mission-card" data-state="NOTICE" data-action="notice"><small>${c.notice||'IMPORTANT'}</small><b>${state.notice?(c.noticeConfirmed||'公告已确认'):(c.noticeTitle||'活动参与说明')}</b><span>${state.notice?'状态已记录':'打开不等于确认'}</span><i>!</i></button></div></section>`;}
function eventsPage(){const c=pageCopy('events'),list=visibleEvents(),clubs=eventClubOptions(),created=list.find(e=>e.id===state.lastCreatedEventId),createdBanner=created?`<div class="created-event-receipt" data-component="created-event-receipt"><div><small>MISSION CREATED / 演示完成</small><b>${esc(created.title)}</b><span>已加入活动列表 · ${esc(created.date)} · 发起者已计入 ${created.count}/${created.capacity}</span></div>${p5btn('查看活动详情','event',created.id,'white')}</div>`:'',filtered=filteredEvents(list),clubFilters=[['all','全部社团'],...clubs.map(club=>[club.id,club.name]),['other','其他公开活动']];return `<section class="screen events-screen" data-page="events" data-theme-surface="mission-grid"><div class="screen-shade"></div><div class="events-layout">${title(c.eyebrow||'FIND YOUR PEOPLE',c.title||'发现',c.titleEm||'活动')}${createdBanner}<span class="sr-only">选择行动</span><p class="lead">${c.lead||'先看人数、流程和社交强度，再决定要不要参加。'}</p>${backendDataNotice('events','活动')}<div class="low-pressure-note"><b>不需要马上报名</b><span>可以先记录兴趣，或私下表达想找同行；这些动作不会占用活动名额。</span></div><section class="event-club-filter" aria-label="按社团查看活动"><div><small>CLUB ACTIVITY INDEX / 社团活动分类</small><b>先按社团分开看，再决定行动</b></div><div class="event-club-filter-list">${clubFilters.map(([id,label])=>`<button data-action="event-club-filter" data-id="${esc(id)}" class="${state.eventClubFilter===id?'active':''}" aria-pressed="${state.eventClubFilter===id}">${esc(label)}</button>`).join('')}</div></section><div class="filter-ribbon">${['全部','正式活动','成员聚会','我感兴趣','我的活动'].map(f=>`<button data-action="filter" data-id="${f}" class="${state.filter===f?'active':''}" aria-pressed="${state.filter===f}">${f}</button>`).join('')}<input id="event-search" type="search" value="${esc(state.query)}" placeholder="${c.search||'搜索活动…'}" aria-label="搜索活动"></div><div id="mission-list" class="mission-list">${filtered.map(eventCard).join('')||p5Empty(c.empty||'暂时没有匹配活动',c.emptyHint||'调整筛选条件，或发起一个轻松的小聚。',c.emptyCode||'NO ACTIVITY')}</div><div style="margin-top:15px">${p5btn(c.gather||'＋ 发起一个小聚','gathering','','red')}</div></div></section>`;}
function publicClub(){const list=activeEvents(),upcoming=list.filter(e=>e.type==='正式活动').slice(0,2),memberEvents=list.filter(e=>e.type==='成员聚会').slice(0,2);show(`<div class="public-club-sheet"><div class="public-club-hero"><span class="tag">PUBLIC CLUB PROFILE / 演示</span><h2 id="dialog-title">幻影动漫社</h2><p>给喜欢动画、游戏和创作的人，一个不用先证明自己的校园据点。</p><div class="public-club-facts"><span><b>128</b>社团成员</span><span><b>${list.length}</b>近期活动</span><span><b>LOW</b>压力入口</span></div></div><section class="public-club-section"><small>WHAT WE DO / 社团介绍</small><h3>先从一次轻松参与开始</h3><p>这里可以查看公开活动、了解加入方式，再决定是否进入小组。公开主页只展示社团定位和活动信息，不公开成员个人状态。</p></section><section class="public-club-section"><small>NEXT SIGNALS / 近期公开活动</small><div class="public-club-events">${[...upcoming,...memberEvents].map(e=>`<button data-action="event" data-id="${e.id}"><b>${esc(e.title)}</b><span>${esc(e.date)} · ${esc(e.type)}</span></button>`).join('')||'<p>暂时没有公开活动。</p>'}</div></section><section class="public-club-section public-club-rules"><small>OPEN POLICY / 公开说明</small><div><span>✓ 新生可以先看活动，不必立即加入</span><span>✓ 兴趣和找同行不会占名额</span><span>✓ 示例数据不代表真实通知或权限</span></div></section><div class="dialog-actions">${p5btn('进入同好与小组','goto','community','white')}${p5btn('关闭主页','close','','ghost')}</div></div>`, 'wide-dialog public-club-dialog')}

function community(){const c=pageCopy('community'),clubList=activeGroups(),squads=visibleEvents().filter(e=>e.type==='成员聚会').slice(0,3);return `<section class="screen community-screen" data-page="community" data-theme-surface="orbit-link"><div class="screen-shade"></div><div class="community-wrap">${title(c.eyebrow||'FIND YOUR PEOPLE',c.title||'同好',c.titleEm||'同行')}<p class="lead">${c.lead||'稳定小组和一次性活动小队，都可以从一次轻松的回应开始。'}</p><div class="public-club-entry"><div><small>PUBLIC CLUB / 公开入口</small><b>先了解社团，再决定要不要加入</b><span>查看社团定位、公开活动和参与规则。</span></div>${p5btn('查看社团主页','public-club','','white')}</div><div class="community-grid">${clubList.map(g=>`<article class="bond-card" data-component="group-card" data-group-id="${esc(g.id)}" data-state="${state.joined.has(g.id)?'JOINED':'AVAILABLE'}"><span class="symbol">${g.symbol}</span><small>${esc(g.tag)} / ${g.members} PEOPLE</small><h2>${esc(g.name)}</h2><p>${esc(g.desc)}</p><button data-action="group" data-id="${g.id}">${state.joined.has(g.id)?(c.joined||'已加入小组'):(c.join||'了解并加入')} ↗</button></article>`).join('')}</div>${backendDataNotice('clubs','社团')}<section class="squad-panel" data-component="temporary-squads"><div class="squad-heading"><div><small>SHORT-TERM SQUADS / 本次活动</small><h2>临时活动小队</h2><p>只为这一次活动结伴，不需要先加入长期社团。你可以先看清集合信息，再留下同行意向。</p></div><span class="squad-count">${state.squadJoined.size} / ${squads.length}<small>已加入演示小队</small></span></div><div class="squad-list">${squads.length?squads.map(e=>{const joined=state.squadJoined.has(e.id),f=formationInfo(e);return `<article class="squad-row ${joined?'is-joined':''}"><div class="squad-row-main"><div><b>${esc(e.title)}</b><span>${esc(e.date)} · ${esc(e.place)}</span></div><small>${f.label} · ${e.count}/${e.capacity} 人${joined?' · 你已留下意向':''}</small></div><div class="squad-row-actions">${p5btn(joined?'已加入':'一起出发','squad',e.id,joined?'ghost':'red')}${p5btn('查看详情','squad-detail',e.id,'ghost')}</div></article>`}).join(''):p5Empty('暂时没有成员聚会','去活动页发起一个轻松的小聚。','NO SQUAD')}</div></section><div class="game-rack">${games.map(g=>`<button class="game-chip ${state.followed.has(g.id)?'on':''}" data-action="game" data-id="${g.id}" aria-label="${state.followed.has(g.id)?'查看':'进入'}${esc(g.name)}专区"><b>${esc(g.name)}</b><small>${esc(g.type)} / ${state.followed.has(g.id)?(c.followed||'已关注'):(c.game||'作为活动标签')}</small></button>`).join('')}</div><div class="link-actions">${p5btn(c.create||'＋ 发起兴趣小组','create-group','','white')}${p5btn(c.files||'小组资料说明','resources','','ghost')}${p5btn(c.places||'校园生活手册','places','','ghost')}</div></div></section>`;}
function me(){const c=pageCopy('me');const regs=[...state.registrations],showLeaderEntry=true;return `<section class="screen me-screen" data-page="me" data-theme-surface="student-dossier"><div class="screen-shade"></div><div class="profile-layout"><article class="profile-card" data-component="profile-card" data-state="ACTIVE"><span class="profile-avatar">${esc((state.profile?.nickname||'林同学').slice(0,1))}</span><small>${c.member||'CLUB MEMBER'}</small><h1>${esc(state.profile?.nickname||'林同学')}</h1><p>${state.profile?'真实账号资料 · 当前权限由社团成员关系决定':'普通成员 · 示例身份 · 无管理权限'}</p><div class="profile-stats"><div><b>${regs.length}</b><span>我的活动</span></div><div><b>${state.interest.size}</b><span>兴趣记录</span></div><div><b>${state.companions.size}</b><span>想找同行</span></div><div><b>${state.joined.size}</b><span>已加入小组</span></div></div>${p5btn(c.profile||'查看资料说明','privacy','','white')}</article><div class="record-board">${backendDataNotice('clubs','社团与成员关系')}<section class="paper-panel wide" data-component="panel" data-variant="tickets"><h2>${c.tickets||'MY ACTIVITIES / 我的活动'}</h2>${regs.length?regs.map(([id,status])=>{const e=activeEvents().find(x=>x.id===id);if(!e)return '';return `<div class="record"><div><b>${esc(e.title)}</b><br><small>${e.date} · ${status}</small></div><button data-action="event" data-id="${id}">查看</button></div>`}).join(''):'<div class="empty-note"><b>还没有确认活动</b><br>你可以先表达兴趣，不需要立刻报名。</div>'}</section><section class="paper-panel preference-panel" data-component="panel" data-variant="participation-preferences"><small>LOW-PRESSURE SETTINGS / DEMO</small><h2>参与偏好</h2><div class="preference-list"><span>偏好小规模活动 <b>已开启</b></span><span>想有人一起到场 <b>${state.companions.size?'已记录':'未设置'}</b></span><span>愿意参加新人友好活动 <b>已开启</b></span><span>允许中途离开的活动 <b>已开启</b></span><span>不公开显示参加状态 <b>已开启</b></span></div><p class="hint">偏好只在本地演示中展示，尚未连接真实通知或匹配服务。</p></section>${showLeaderEntry?`<section class="paper-panel leader-entry" data-component="panel" data-variant="command-preview"><small>${hasLiveLeaderAccess()?'CLUB STAFF / REAL READ':'CLUB STAFF PREVIEW / DEMO'}</small><h2>${hasLiveLeaderAccess()?'社长工作台':state.authStatus==='authenticated'?'创建你的社团':'活动发起与管理预览'}</h2><p>${hasLiveLeaderAccess()?'当前账号拥有 active leader/admin 社团关系。可读取本人社团的真实活动，并管理社团资料。':state.authStatus==='authenticated'?'当前账号尚无负责的社团。创建后即可进入真实社长工作台；普通社员身份不受影响。':'这里仅用于预览发起活动、查看意向和发布说明，不会静默授予真实权限。'}</p>${hasLiveLeaderAccess()?`${p5btn('打开社长工作台 ↗','leader-console','','red')}${p5btn('编辑社团','edit-leader-club',state.leaderClubId,'ghost')}`:state.authStatus==='authenticated'?p5btn('创建新社团','create-club','','red'):p5btn('打开管理预览 ↗','leader-console','','red')}</section>`:''}<section class="paper-panel theme-contract" data-component="panel" data-variant="theme-contract"><small>THEME SYSTEM / READY</small><h2>主题外观</h2><div class="theme-current"><span>ACTIVE</span><b>${esc(activeTheme().displayName)}</b><em>${esc(activeTheme().label)}</em></div><p>业务结构、状态语义与作品素材已分层。主题只改变视觉层，不改变活动状态。</p><div class="status-protocol" aria-label="统一状态语义">${statusLegend()}</div><span class="theme-reserved">OTHER WORKS / RESERVED</span></section><section class="paper-panel" data-component="panel" data-variant="options"><h2>${c.options||'OPTIONS / 偏好'}</h2><label class="settings-line"><span>减少页面动效</span><input id="motion" type="checkbox" ${state.reduced?'checked':''}></label><div class="record"><span>页面音效</span><b>${state.sound?'ON':'OFF'}</b></div><div class="record"><span>演示数据</span><b>刷新重置</b></div></section></div></div></section>`;}
function render(){main.innerHTML=({hub,events:eventsPage,community,me})[state.page]();updateBeijingClock();document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===state.page);if(a.dataset.route===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});state.tip=0;$('#advisor-text').textContent=tipsFor(state.page)[0];document.title=`${labels[state.page]} / ${activeTheme().titleSuffix}`;updateMail()}
function navigate(target,push=true){if(!pages.includes(target)||target===state.page||state.switching)return;state.switching=true;transition.dataset.motion=activeTheme().motion?.transition||'p5-slice';transition.dataset.state='PLAYING';transition.classList.add('play');try{transitionVideo.currentTime=0;transitionVideo.play().catch(()=>{})}catch(e){};sfx('transition');setTimeout(()=>{state.page=target;render();if(push)history.pushState({page:target},'',`#${target}`);main.focus({preventScroll:true})},320);setTimeout(()=>{transition.classList.remove('play');transition.dataset.state='IDLE';state.switching=false;showPageIntro(target)},760)}
