function clearFormError(form){form?.querySelectorAll('[aria-invalid="true"]').forEach(field=>{field.removeAttribute('aria-invalid');const ids=(field.getAttribute('aria-describedby')||'').split(/\s+/).filter(id=>id&&id!=='form-error');if(ids.length)field.setAttribute('aria-describedby',ids.join(' '));else field.removeAttribute('aria-describedby')});const error=form?.querySelector('.form-error');if(error){error.textContent='';error.setAttribute('aria-hidden','true')}}
