 const steps=`<ol class="upload-demo-steps" aria-label="上传流程演示阶段">${uploadDemoStages.map(([key,label],index)=>`<li class="${index<stepIndex?'done':index===stepIndex?'active':''}" ${index===stepIndex?'aria-current="step"':''}><i>${String(index+1).padStart(2,'0')}</i><span>${label}</span></li>`).join('')}</ol>`;
