function confirmMemberAction(id,action){const member=clubMembers.find(x=>x.id===id);if(!member)return;show(`<div class="danger-confirm"><small>HIGH RISK COMMAND</small><h2 id="dialog-title">确认${action==='freeze'?'冻结':'移除'}成员？</h2><p>目标：<b>${esc(member.name)}</b>。该操作在真实系统中必须记录操作者、时间与原因，并允许授权管理员复核。</p><label class="field">操作原因<input id="danger-reason" maxlength="120" placeholder="请说明原因"></label><div class="dialog-actions">${p5btn('返回工作台','leader-console','','ghost')}${p5btn('确认执行','confirm-member-action',id+':'+action,'red')}</div></div>`,'danger-dialog')}

